// ── Org: Registry (agents table) ────────────────────────────────────────────

function loadRegistry() {
  const agents = {};
  for (const row of stmt('SELECT * FROM agents').all()) {
    const extra = JSON.parse(row.extra || '{}');
    agents[row.id] = {
      ...row,
      breakdown: JSON.parse(row.breakdown || '{}'),
      stats: JSON.parse(row.stats || '{}'),
      skills: JSON.parse(row.skills || '{}'),
      pip: row.pip ? JSON.parse(row.pip) : null,
      canMentor: extra.canMentor,
      canShipProd: extra.canShipProd,
      levelColor: extra.levelColor,
      weaknesses: extra.weaknesses,
      computedAt: extra.computedAt,
    };
    delete agents[row.id].extra;
  }
  return { version: 1, agents, updatedAt: new Date().toISOString() };
}

function saveRegistry(data) {
  if (!data || !data.agents) return;
  const db = getDb();
  const s = db.prepare('INSERT OR REPLACE INTO agents (id,name,description,department,phase,reportsTo,title,tier,role,model,hiredAt,status,level,levelTitle,yearsOfExperience,experiencePoints,progressToNext,nextLevelTitle,lastPromoted,lastReview,retiredAt,retiredReason,breakdown,stats,skills,pip,extra,updatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
  db.transaction(() => {
    for (const [id, a] of Object.entries(data.agents)) {
      s.run(id, a.name, a.description, a.department, a.phase, a.reportsTo, a.title, a.tier, a.role, a.model, a.hiredAt, a.status, a.level, a.levelTitle, a.yearsOfExperience, a.experiencePoints, a.progressToNext, a.nextLevelTitle, a.lastPromoted, a.lastReview, a.retiredAt, a.retiredReason, JSON.stringify(a.breakdown || {}), JSON.stringify(a.stats || {}), JSON.stringify(a.skills || {}), a.pip ? JSON.stringify(a.pip) : null, JSON.stringify({ canMentor: a.canMentor, canShipProd: a.canShipProd, levelColor: a.levelColor, weaknesses: a.weaknesses, computedAt: a.computedAt }), a.updatedAt || new Date().toISOString());
    }
  })();
}

