router.get('/org/drift', rateLimit('read'), (req, res) => {
  try {
    const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
    const agentMap = Object.fromEntries(globalAgents.map((a) => [a.filename, a]));
