export default function OrgChartPage() {
  const [data, setData] = useState<OrgChartData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [view, setView] = useState<ViewType>('tree')
  const [expanded, setExpanded] = useState<Set<string>>(new Set(['rex', 'arya']))
  const [search, setSearch] = useState('')
  const [selectedNode, setSelectedNode] = useState<string | null>(null)
  const [drift, setDrift] = useState<DriftData | null>(null)
  const [globalAgents, setGlobalAgents] = useState<Agent[]>([])
  const [configureId, setConfigureId] = useState<string | null>(null)
  const [live, setLive] = useState(false)

  const loadData = useCallback(() => {
    setLoading(true)
    Promise.all([
      getOrgChart(),
      getDrift().catch(() => ({ onlyOnDisk: [], onlyInRegistry: [] })),
      getGlobalAgents().catch(() => []),
    ])
      .then(([chart, driftData, agents]) => {
        setData(chart)
        setDrift(driftData)
        setGlobalAgents(agents)
        setError(null)
      })
      .catch((e: unknown) => {
        setError(e instanceof Error ? e.message : 'Failed to load org chart')
      })
      .finally(() => setLoading(false))
  }, [])

  // Silent refetch triggered by SSE. Debounced so a burst of file events (e.g.
  // `git checkout` touching many agents) does not cause refetch storms.
  const refetchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const scheduleRefetch = useCallback(() => {
    if (refetchTimerRef.current) clearTimeout(refetchTimerRef.current)
    refetchTimerRef.current = setTimeout(() => {
      Promise.all([
        getOrgChart(),
        getDrift().catch(() => ({ onlyOnDisk: [], onlyInRegistry: [] })),
        getGlobalAgents().catch(() => []),
      ])
        .then(([chart, driftData, agents]) => {
          setData(chart)
          setDrift(driftData)
          setGlobalAgents(agents)
        })
        .catch(() => {})
    }, 300)
  }, [])

  useEffect(() => {
    loadData()
  }, [loadData])

  useEffect(() => {
    const es = subscribeOrgChart((ev) => {
      if (ev.type === 'ready') {
        setLive(true)
        return
      }
      if (ev.type === 'agent:upsert' || ev.type === 'agent:remove') {
        scheduleRefetch()
      }
    })
    es.onopen = () => setLive(true)
    es.onerror = () => setLive(false)
    return () => {
      if (refetchTimerRef.current) clearTimeout(refetchTimerRef.current)
      es.close()
    }
  }, [scheduleRefetch])

